class ArgumentParser:
    DEFAULT_FLAGS = {'--', '-'}
    FLAG_SEPARATOR = '='
    FLAG_PREFIX_LONG = '--'
    FLAG_PREFIX_SHORT = '-'
    OPTION_VALUE_POSITION = 1

    def __init__(self):
        self._arguments = {}
        self._required = set()
        self._types = {}

    def parse_arguments(self, command_string):
        args = self._extract_arguments(command_string)
        for i, arg in self._iter_args_with_values(args):
            if self._is_long_flag(arg):
                self._handle_long_flag(arg)
            elif self._is_short_flag(arg):
                self._handle_short_flag(arg, args, i)

        missing_args = self._get_missing_required_args()
        if missing_args:
            return False, missing_args

        return True, None

    def get_argument(self, key):
        return self._arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        if required:
            self._required.add(arg)
        self._types[arg] = arg_type

    def _extract_arguments(self, command_string):
        return command_string.split()[1:]

    def _iter_args_with_values(self, args):
        for i in range(len(args)):
            yield i, args[i]

    def _is_long_flag(self, arg):
        return arg.startswith(self.FLAG_PREFIX_LONG)

    def _is_short_flag(self, arg):
        return arg.startswith(self.FLAG_PREFIX_SHORT)

    def _handle_long_flag(self, arg):
        key_value = arg[len(self.FLAG_PREFIX_LONG):].split(self.FLAG_SEPARATOR)
        if len(key_value) == 2:
            self._arguments[key_value[0]] = self._convert_type(key_value[0], key_value[1])
        else:
            self._arguments[key_value[0]] = True

    def _handle_short_flag(self, arg, args, index):
        key = arg[len(self.FLAG_PREFIX_SHORT):]
        if self._has_value_following(index, args):
            self._arguments[key] = self._convert_type(key, args[index + 1])
        else:
            self._arguments[key] = True

    def _has_value_following(self, index, args):
        return index + 1 < len(args) and not args[index + 1].startswith('-')

    def _get_missing_required_args(self):
        return self._required - set(self._arguments.keys())

    def _convert_type(self, arg, value):
        return self._safe_convert(arg, value)

    def _safe_convert(self, arg, value):
        try:
            return self._types[arg](value)
        except (ValueError, KeyError):
            return value
